18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles {@link InvalidOwnerFieldsException} thrown when an owner is created or updated with
128	     * required fields that are missing or blank (for example, whitespace-only values that Bean
129	     * Validation does not reject). Returns a 400 Bad Request whose {@code errors} array lists the
130	     * name of each offending field.
131	     *
132	     * @param e The {@link InvalidOwnerFieldsException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
135	     */
136	    @ExceptionHandler(InvalidOwnerFieldsException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
139	        logger.debug("Invalid owner fields at {} {}: {}",
140	            request.getMethod(),
141	            request.getRequestURI(),
142	            e.getFields());
143	        HttpStatus status = HttpStatus.BAD_REQUEST;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
145	        detail.setProperty("errors", e.getFields());
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles {@link DuplicateOwnerTelephoneException} thrown when an owner is created with a
151	     * normalized telephone that is already used by another owner. Returns a 409 Conflict whose
152	     * {@code errors} array names {@code telephone}.
153	     *
154	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
157	     */
158	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
161	        logger.debug("Duplicate owner telephone at {} {}: {}",
162	            request.getMethod(),
163	            request.getRequestURI(),
164	            e.getTelephone());
165	        HttpStatus status = HttpStatus.CONFLICT;
166	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
167	        detail.setProperty("errors", List.of("telephone"));
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link DuplicateOwnerHouseholdException} thrown when an owner is created whose last
173	     * name and address already belong to another owner (compared case-insensitively with collapsed
174	     * whitespace) and the request did not opt in with {@code sharesHousehold}. Returns a 409 Conflict
175	     * whose {@code errors} array names {@code lastName} and {@code address}.
176	     *
177	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
178	     * @param request {@link HttpServletRequest} object referring to the current request.
179	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
180	     */
181	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
182	    @ResponseBody
183	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
184	        logger.debug("Duplicate owner household at {} {}: {}, {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getLastName(),
188	            e.getAddress());
189	        HttpStatus status = HttpStatus.CONFLICT;
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
191	        detail.setProperty("errors", List.of("lastName", "address"));
192	        return ResponseEntity.status(status).body(detail);
193	    }
194	
195	    /**
196	     * Handles exception thrown by Bean Validation on controller methods parameters
197	     *
198	     * @param e The {@link MethodArgumentNotValidException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
201	     */
202	    @ExceptionHandler(MethodArgumentNotValidException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
205	        HttpStatus status = HttpStatus.BAD_REQUEST;
206	        BindingErrorsResponse errors = new BindingErrorsResponse();
207	        BindingResult bindingResult = e.getBindingResult();
208	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
209	        if (bindingResult.hasErrors()) {
210	            errors.addAllErrors(bindingResult);
211	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
212	                .map(FieldError::getField)
213	                .distinct()
214	                .toList();
215	            detail.setProperty("errors", invalidFields);
216	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
217	                .map(fieldError -> {
218	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
219	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
220	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
221	                        fieldError.getField(),
222	                        defaultMessage,
223	                        rejectedValue);
224	                    return new ValidationMessageDto(message)
225	                        .putAdditionalProperty("field", fieldError.getField())
226	                        .putAdditionalProperty("rejectedValue", rejectedValue)
227	                        .putAdditionalProperty("defaultMessage", defaultMessage);
228	                })
229	                .toList();
230	            logger.debug("Validation error at {} {}: {}",
231	                request.getMethod(),
232	                request.getRequestURI(),
233	                bindingResult.getFieldErrors());
234	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
235	            return ResponseEntity.status(status).body(detail);
236	        }
237	        return ResponseEntity.status(status).body(detail);
238	    }
239	
240	}
